\begin{lemma}
\label{lemma-abelian}
Let $B \to S$ as in Section \ref{section-notation}.
Let $(U, R, s, t, c)$ be a groupoid in algebraic spaces over $B$.
If $s$, $t$ are flat, then the category of quasi-coherent modules on
$(U, R, s, t, c)$ is abelian.
\end{lemma}

